// Concert: pass JSON strings between blocks; read dollar-prefixed variables only at block top level.
// Concert: keep dollar characters out of comments and avoid block-result references in inputs.
// GPU requests distinguish inference pods from KServe routers sharing the same label.
function unwrap(v) {
    var keys = ["body", "data", "payload", "response", "result"];
    for (var depth = 0; depth < 5; depth++) {
        if (typeof v === "string") { v = JSON.parse(v); }
        if (!v || typeof v !== "object") { break; }
        if (v.spec || v.items || v.kind) { return v; }
        var next;
        for (var i = 0; i < keys.length; i++) {
            if (v[keys[i]] !== undefined) { next = v[keys[i]]; break; }
        }
        if (next === undefined) { break; }
        v = next;
    }
    return v;
}

function require_(v, blockName, what, test) {
    var got = unwrap(v);
    if (!test(got)) {
        throw new Error("$" + blockName + ".result is not " + what +
                        " -- got: " + JSON.stringify(got).substring(0, 400));
    }
    return got;
}

function isList(o) { return o && o.items instanceof Array; }
function verdict(id, title, ok, detail, evidence) {
    return JSON.stringify({ id: id, title: title, ok: !!ok, detail: detail,
                            evidence: evidence || {} });
}
var pods = require_($HTTPRequest_1.result, "HTTPRequest_1", "a Pod list", isList);
var GPU_RES = $gpu_resource;
var PLAIN_RES = $plain_gpu_resource;
var NS_NAME = $llm_namespace;
function gpuContainers(pod) {
    var out = [];
    var all = [].concat(pod.spec.initContainers || [], pod.spec.containers);
    for (var c = 0; c < all.length; c++) {
        var lim = (all[c].resources || {}).limits || {};
        if (lim[GPU_RES] === undefined && lim[PLAIN_RES] === undefined) { continue; }
        out.push({
            container: all[c].name,
            pgpu: lim[GPU_RES] !== undefined ? String(lim[GPU_RES]) : "",
            gpu: lim[PLAIN_RES] !== undefined ? String(lim[PLAIN_RES]) : ""
        });
    }
    return out;
}
function terminating(pod) {
    var phase = (pod.status || {}).phase;
    return !!(pod.metadata || {}).deletionTimestamp || phase === "Succeeded" || phase === "Failed";
}
var subjects = [];
var initdatas = [];
var skipped = 0;
for (var p = 0; p < pods.items.length; p++) {
    var cand = pods.items[p];
    if (!cand.spec || !(cand.spec.containers instanceof Array)) { continue; }
    var gpus = gpuContainers(cand);
    if (gpus.length === 0) { continue; }
    if (terminating(cand)) { skipped++; continue; }
    var annotations = (cand.metadata || {}).annotations || {};
    subjects.push({
        name: (cand.metadata || {}).name || "unknown",
        runtime_class: cand.spec.runtimeClassName || "",
        node: cand.spec.nodeName || "",
        initdata: annotations["coco.io/initdata-configmap"] || "",
        gpus: gpus
    });
    initdatas.push(annotations["io.katacontainers.config.hypervisor.cc_init_data"] || "");
}

if (subjects.length === 0) {
    throw new Error("no non-terminating GPU-requesting pod found in namespace '" + NS_NAME +
                    "' -- saw " + pods.items.length + " pod(s), " + skipped +
                    " terminating. Is the LLM deployed?");
}

$llm_cc_init_data = JSON.stringify(initdatas);
$llm_pods = JSON.stringify(subjects);

