        if (v.spec || v.items || v.kind) { return v; }
        var next;
        for (var i = 0; i < keys.length; i++) {
            if (v[keys[i]] !== undefined) { next = v[keys[i]]; break; }
        }
        if (next === undefined) { break; }
        v = next;
    }
    return v;
}

function require_(v, blockName, what, test) {
    var got = unwrap(v);
    if (!test(got)) {
        throw new Error("$" + blockName + ".result is not " + what +
                        " -- got: " + JSON.stringify(got).substring(0, 400));
    }
    return got;
}

function isList(o) { return o && o.items instanceof Array; }
function verdict(id, title, ok, detail, evidence) {
    return JSON.stringify({ id: id, title: title, ok: !!ok, detail: detail,
                            evidence: evidence || {} });
}
var rcs = require_($HTTPRequest_2.result, "HTTPRequest_2", "a RuntimeClass list", isList);
var subjects = JSON.parse($llm_pods);
var EXPECTED = $expected_handler;

var allOk = true;
var details = [];
var perPod = [];
for (var s = 0; s < subjects.length; s++) {
    var runtime = subjects[s].runtime_class;
    var handler = "";
    for (var i = 0; i < rcs.items.length; i++) {
        if (rcs.items[i].metadata && rcs.items[i].metadata.name === runtime) {
            handler = rcs.items[i].handler || "";
            break;
        }
    }
    var ok = handler === EXPECTED;
    allOk = allOk && ok;
    details.push(subjects[s].name + ": runtimeclass=" + (runtime || "none") + " handler=" + (handler || "none"));
    perPod.push({ pod: subjects[s].name, ok: ok, runtime_class: runtime || "none", handler: handler || "none" });
}

$check_runtime = verdict(
    "confidential_runtime",
    "Every inference pod runs on an Intel TDX confidential runtime",
    allOk,
    details.join("; ") + " (expected handler=" + EXPECTED + ")",
    { pods: perPod }
);

