var subjects = JSON.parse($llm_pods);
var GPU_RES = $gpu_resource;
var PLAIN_RES = $plain_gpu_resource;

var allOk = true;
var details = [];
var perPod = [];
for (var s = 0; s < subjects.length; s++) {
    var gpus = subjects[s].gpus;
    var pgpu = 0;
    var plainGpu = false;
    for (var j = 0; j < gpus.length; j++) {
        if (gpus[j].pgpu !== "") { pgpu += parseInt(gpus[j].pgpu, 10) || 0; }
        if (gpus[j].gpu !== "") { plainGpu = true; }
    }
    var ok = pgpu >= 1 && !plainGpu;
    allOk = allOk && ok;
    details.push(subjects[s].name + ": " + GPU_RES + "=" + pgpu + " " + PLAIN_RES + "_requested=" + plainGpu);
    perPod.push({ pod: subjects[s].name, ok: ok, confidential_gpus: pgpu, plain_gpu_requested: plainGpu });
}

$check_gpu = verdict(
    "confidential_gpu_passthrough",
    "GPU is passed through confidentially (" + GPU_RES + ", not " + PLAIN_RES + ") in every inference pod",
    allOk,
    details.join("; "),
    { pods: perPod }
);

