function isList(o) { return o && o.items instanceof Array; }
function verdict(id, title, ok, detail, evidence) {
    return JSON.stringify({ id: id, title: title, ok: !!ok, detail: detail,
                            evidence: evidence || {} });
}
var nodes = require_($HTTPRequest_3.result, "HTTPRequest_3", "a Node list", isList);
var subjects = JSON.parse($llm_pods);
var TDX = $tdx_label;
var CC_MODE = $cc_mode_label;
var CC_READY = $cc_ready_label;

var allOk = true;
var details = [];
var perPod = [];
for (var s = 0; s < subjects.length; s++) {
    var nodeName = subjects[s].node;
    var labels = null;
    for (var k = 0; k < nodes.items.length; k++) {
        var md = nodes.items[k].metadata || {};
        if (md.name === nodeName) { labels = md.labels || {}; break; }
    }
    var onTdx   = !!labels && labels[TDX] === "true";
    var ccMode  = !!labels && labels[CC_MODE] === "on";
    var ccReady = !!labels && labels[CC_READY] === "true";
    var ok = onTdx && ccMode && ccReady;
    allOk = allOk && ok;
    details.push(subjects[s].name + ": node=" + (nodeName || "unknown") + " tdx=" + onTdx +
                 " cc.mode=" + ccMode + " cc.ready=" + ccReady);
    perPod.push({ pod: subjects[s].name, ok: ok, node: nodeName || "unknown", tdx: onTdx,
                  cc_mode_on: ccMode, cc_ready: ccReady });
}

$check_platform = verdict(
    "platform_tdx_and_gpu_cc_mode",
    "Every inference pod's host exposes Intel TDX and its GPU is in CC mode and ready",
    allOk,
    details.join("; "),
    { pods: perPod }
);

