function isList(o) { return o && o.items instanceof Array; }
function verdict(id, title, ok, detail, evidence) {
    return JSON.stringify({ id: id, title: title, ok: !!ok, detail: detail,
                            evidence: evidence || {} });
}
var cm = require_($HTTPRequest_6.result, "HTTPRequest_6", "a ConfigMap with data.INITDATA",
                  function (o) { return o && o.data && typeof o.data.INITDATA === "string"; });
var CM_NS = $initdata_namespace;
var CM_NAME = $expected_initdata;
var expectedInitdata = cm.data.INITDATA;
if (expectedInitdata === "") {
    throw new Error("ConfigMap " + CM_NS + "/" + CM_NAME + " has an empty INITDATA -- cannot " +
                    "check the init_data policy");
}
var ref = String(cm.data.RAW_HASH || "").replace(/\s+/g, "").toLowerCase();

var podInitdatas = JSON.parse($llm_cc_init_data);
var subjects = JSON.parse($llm_pods);

var allOk = true;
var details = [];
var perPod = [];
for (var s = 0; s < subjects.length; s++) {
    var podInitdata = podInitdatas[s] || "";
    var present = podInitdata !== "";
    var match = present && podInitdata === expectedInitdata;
    allOk = allOk && match;
    details.push(subjects[s].name + ": " + (!present
        ? "no io.katacontainers.config.hypervisor.cc_init_data annotation"
        : "cc_init_data (" + podInitdata.length + " chars) " +
          (match ? "is byte-identical to" : "differs from") + " the reference"));
    perPod.push({
        pod: subjects[s].name,
        ok: match,
        pod_cc_init_data_present: present,
        pod_cc_init_data_length: podInitdata.length,
        pod_cc_init_data_matches_reference: match,
        initdata_annotation_info_only: subjects[s].initdata || "none"
    });
}

$check_initdata = verdict(
    "locked_measured_boot_policy",
    "Every LLM pod is configured to boot the locked init_data policy (no exec/log access)",
    allOk,
    details.join("; ") + "; reference = INITDATA of " + CM_NS + "/" + CM_NAME + " (" +
        expectedInitdata.length + " chars), RAW_HASH=" + (ref || "absent").substring(0, 16) +
        "... is what the hub RVPS expects",
    {
        pods: perPod,
        reference_configmap: CM_NS + "/" + CM_NAME,
        reference_initdata_length: expectedInitdata.length,
        reference_raw_hash: ref || "absent"
    }
);

// Concert: pass JSON strings between blocks; read dollar-prefixed variables only at block top level.
// Concert: keep dollar characters out of comments and avoid block-result references in inputs.
// A missing verdict is an execution error, not a non-compliant result.
var NS = "https://oscal-compass.github.io/compliance-trestle/schemas/oscal/ar/OpenSCAP";
var raw = [$check_runtime, $check_gpu, $check_initdata, $check_platform];
var checks = [];
for (var r = 0; r < raw.length; r++) {
    checks.push(typeof raw[r] === "string" && raw[r] !== "" ? JSON.parse(raw[r]) : raw[r]);
}
var names  = ["Check_ConfidentialRuntime", "Check_ConfidentialGpuPassthrough",
              "Check_LockedMeasuredBootPolicy", "Check_PlatformTdxAndGpuCcMode"];
for (var v = 0; v < checks.length; v++) {
    if (!checks[v] || typeof checks[v].ok !== "boolean") {
        throw new Error("block " + names[v] + " produced no verdict -- refusing to report a " +
                        "compliance result from an incomplete run");
    }
}

var failed = [];
for (var f = 0; f < checks.length; f++) { if (!checks[f].ok) { failed.push(checks[f].id); } }
var passed = failed.length === 0;
var result = passed ? "pass" : "fail";

function uuid4() {
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0;
        return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16);
    });
}

var now = new Date().toISOString();
var SYSTEM_UUID    = uuid4();
var VALIDATOR_UUID = uuid4();
var PLATFORM_UUID  = uuid4();

var CHECK_IDS = $oscal_check_ids;
if (!(CHECK_IDS instanceof Array)) { CHECK_IDS = String(CHECK_IDS).split(","); }
for (var ci = 0; ci < CHECK_IDS.length; ci++) {
    CHECK_IDS[ci] = String(CHECK_IDS[ci]).replace(/^\s+/, "").replace(/\s+$/, "");
}
if (CHECK_IDS.length === 0 || CHECK_IDS[0] === "") {
    throw new Error("oscal_check_ids is empty -- set the ISCF control ids to report against");
}
var INV_UUID = {};
for (var q = 0; q < CHECK_IDS.length; q++) { INV_UUID[CHECK_IDS[q]] = uuid4(); }
var ENVIRONMENT  = $oscal_environment;
var TARGET_TYPE  = $oscal_target_type;
var PROFILE_NAME = $oscal_profile_name;

function prop(name, value) { return { name: name, ns: NS, value: value }; }

var expected = {
    Validate: "LLM_inference_is_configured_for_an_Intel_TDX_guest_with_a_confidential_GPU_and_the_locked_init_data",
    checks: [
        "assessed: every non-terminating GPU-requesting pod in " + $llm_namespace + "; each must pass every check",
        "confidential_runtime: RuntimeClass handler = " + $expected_handler,
        "confidential_gpu_passthrough: " + $gpu_resource + " >= 1 and no " + $plain_gpu_resource,
        "locked_measured_boot_policy: each pod cc_init_data annotation = INITDATA of " + $initdata_namespace + "/" + $expected_initdata + " (byte-identical)",
        "platform_tdx_and_gpu_cc_mode: " + $tdx_label + "=true, " + $cc_mode_label + "=on, " + $cc_ready_label + "=true"
    ],
    not_checked: "attestation evidence (Trustee appraisal of the running guest and GPU)",
    apis_used: [
        "GET /api/v1/namespaces/" + $llm_namespace + "/pods?labelSelector=" + $llm_pod_selector,
        "GET /apis/node.k8s.io/v1/runtimeclasses",
        "GET /api/v1/nodes?labelSelector=" + $tdx_label + "=true",
        "GET /api/v1/namespaces/" + $initdata_namespace + "/configmaps/" + $expected_initdata
    ]
};

var subjects = JSON.parse($llm_pods);
var PODS = [];
for (var sp = 0; sp < subjects.length; sp++) { PODS.push(subjects[sp].name); }

var actual = {
    compliance_result: result,
    failed_checks: failed,
    checks: checks,
    pods: PODS,
    message: passed ? "LLM_configured_for_Intel_TDX_with_a_confidential_GPU_and_locked_init_data"
                    : "LLM_confidentiality_not_proven: " + failed.join(",")
};

function evidence(checkId) {
    return "# Expected Value\n\n```json\n" + JSON.stringify(expected, null, 2) +
           "\n```\n\n## " + INV_UUID[checkId] + "\n\n```json\n" +
           JSON.stringify(actual, null, 2) + "\n```";
}

function inventoryItem(checkId) {
    return {
        uuid: INV_UUID[checkId],
        description: checkId,
        props: [
            prop("target", ENVIRONMENT),
            prop("target_type", TARGET_TYPE),
            prop("finding_count", String(CHECK_IDS.length))
        ],
        "implemented-components": [{ "component-uuid": SYSTEM_UUID }]
    };
}

function observation(checkId) {
    return {
        uuid: uuid4(),
        description: "Compliance check for confidential LLM inference (Intel TDX + NVIDIA CC): " + checkId,
        props: [
            prop("idref", checkId),
            prop("result", result),
            prop("time", now),
            prop("severity", "high")
        ],
        methods: ["TEST-AUTOMATED"],
        subjects: [{ "subject-uuid": INV_UUID[checkId], type: "inventory-item" }],
        collected: now,
        "relevant-evidence": [{ description: evidence(checkId) }]
    };
}

var inventoryItems = [];
var observations   = [];
for (var t = 0; t < CHECK_IDS.length; t++) {
    inventoryItems.push(inventoryItem(CHECK_IDS[t]));
    observations.push(observation(CHECK_IDS[t]));
}

$assessment_result = {
    results: [{
        uuid: uuid4(),
        title: "Sovereign core controls",
        description: "Sovereign Core assessment results.",
        start: now,
        end: now,
        "local-definitions": {
            components: [{
                uuid: SYSTEM_UUID,
                description: "Compliance assessment results from all sovereign control frameworks.",
                status: { state: "operational" },
                title: "Sovereign Software",
                type: "system"
            }],
            "inventory-items": inventoryItems,
            "assessment-assets": {
                components: [{
                    uuid: VALIDATOR_UUID,
                    type: "Validator",
                    title: "Sovereign Validation",
                    description: "Automated validation compliance",
                    props: [
                        prop("scanner_name", "Sovereign Validation"),
                        prop("scanner_version", "1.0.0"),
                        prop("scan_method", "checks"),
                        prop("version", "0.0.1"),
                        prop("id", PROFILE_NAME)
                    ],
                    status: { state: "operational" }
                }],
                "assessment-platforms": [{ uuid: PLATFORM_UUID }]
            }
        },
        "reviewed-controls": { "control-selections": [{}] },
        observations: observations
    }]
};
